SELECT relname, last_autovacuum, last_autoanalyze, n_dead_tup
FROM pg_stat_user_tables ORDER BY n_dead_tup DESC LIMIT 5;
ANALYZE big_table;

ALTER SYSTEM SET autovacuum_vacuum_cost_limit = 2000;
ALTER SYSTEM SET autovacuum_max_workers = 6;     -- needs restart
SELECT pg_reload_conf();
ALTER TABLE events SET (autovacuum_vacuum_cost_limit = 4000);

SELECT relname, n_dead_tup,
       round(100.0 * n_dead_tup / nullif(n_live_tup + n_dead_tup, 0), 1) AS dead_pct,
       last_autovacuum, autovacuum_count
FROM pg_stat_all_tables ORDER BY dead_pct DESC NULLS LAST LIMIT 10;

SELECT pid, now() - xact_start AS running, query
FROM pg_stat_activity WHERE query LIKE 'autovacuum:%';

SELECT * FROM pg_stat_progress_vacuum;
SELECT * FROM pgstattuple('events');
